            var tmp5 = s[i];
            var j = i - 1;
            var tmp6 = s[j];
            var d = tmp5.Utilization - tmp6.Utilization;
            var dt = (tmp5.Timestamp - tmp6.Timestamp).TotalSeconds;
            var i1 = i + 1;
            if (dt <= 0.0)
