                var pp1 = pp + Math.Max(0.0, d);
                var sec1 = sec + dt;
                return Burn(s, i1, pp1, sec1);
            }
        }
    }

    public static string ResetLine(double u, string iso, IReadOnlyList<HistorySample> samples, DateTime now)
    {
        var r = Format.ParseISO(iso);
        if (r == null)
        {
            return "No active 5-hour window — starts on your next Claude request";
        }
         else if (r.Value <= now)
        {
            return "Window just reset — refreshing soon";
        }
        else
        {
            var c = Format.ClockTime(r.Value);
            var mins = Math.Max(0.0, (r.Value - now).TotalSeconds / 60.0);
            if (u >= CappedAt)
            {
                var m = (int)mins;
                var w = HoursMinutes(m);
                return $"Capped — resets in {(w)} (@ {(c)})";
            }
            else
            {
                var v = Valid(samples);
                var recent = v.Skip(Math.Max(0, v.Count - BurnWindow)).ToList();
                var n = recent.Count;
                if (n < 3)
                {
                    return $"Resets @ {(c)} · click to refresh";
                }
                else
                {
                    var (pp, sec) = Burn(recent, 1, 0.0, 0.0);
                    double rate;
                    if (sec > 0.0)
                    {
                        rate = (pp / sec) * 3600.0;
                    }
                    else
                    {
                        rate = 0.0;
                    }
                    if (rate < IdleBelow)
                    {
                        if (sec < (PollInterval * 2.0))
                        {
                            return $"Resets @ {(c)} · measuring…";
                        }
                        else
                        {
                            return $"Resets @ {(c)} · idle";
                        }
                    }
                    else
                    {
                        var left = Math.Max(0.0, 100.0 - u);
                        double safe;
                        if (mins > 0.0)
                        {
                            safe = (left / mins) * 60.0;
                        }
                        else
                        {
                            safe = 0.0;
                        }
                        var b = (int)Math.Round(rate, MidpointRounding.AwayFromZero);
                        var sf = Math.Max(0, (int)Math.Round(safe, MidpointRounding.AwayFromZero));
                        if (rate > (safe * PaceBuffer))
                        {
                            var to100 = (int)((left / rate) * 60.0);
                            var w = HoursMinutes(to100);
                            return $"Resets @ {(c)} · {(b)}%/h over safe {(sf)}%/h · 100% in {(w)}";
                        }
                        else
                        {
                            return $"Resets @ {(c)} · {(b)}%/h · safe ≤ {(sf)}%/h";
                        }
                    }
                }
            }
        }
    }

    public static string Sparkline(IReadOnlyList<HistorySample> samples, int width)
